import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
test('hidden check', () => {
  const root = fileURLToPath(new URL('..', import.meta.url));
  const items = JSON.parse(readFileSync(root + 'catalog/items.json', 'utf8'));
  assert.equal(items.length, 1000);
  assert.equal(items.find(item => item.sku === 'SKU-0613').region, 'jeju');
  const run = spawnSync(process.execPath, ['scripts/check-catalog.mjs'], {cwd: root, encoding: 'utf8'});
  assert.equal(run.status, 0, run.stdout.slice(-400));
});
